export function getSidebarIconSvgString(nameOrKey: string, size = 16): string {
  const norm = (nameOrKey || '').toLowerCase().replace(/[-_]/g, '');
  
  const keyMap: Record<string, string> = {
    trendline: 'trendLine',
    ray: 'ray',
    infoline: 'infoLine',
    extendedline: 'extendedLine',
    trendangle: 'trendAngle',
    horizontalline: 'horizontalLine',
    priceline: 'horizontalLine',
    horizontalray: 'horizontalRay',
    verticalline: 'verticalLine',
    crossline: 'crossLine',
    parallelchannel: 'parallelChannel',
    regressiontrend: 'regressionTrend',
    flattopbottom: 'flatTopBottom',
    disjointchannel: 'disjointChannel',
    andrewspitchfork: 'andrews',
    andrews: 'andrews',
    pitchfork: 'andrews',
    schiffpitchfork: 'schiff',
    schiff: 'schiff',
    modifiedschiffpitchfork: 'modifiedSchiff',
    modifiedschiff: 'modifiedSchiff',
    insidepitchfork: 'inside',
    inside: 'inside',
    fibretracement: 'retracement',
    retracement: 'retracement',
    fibonacci: 'retracement',
    fibextension: 'extension',
    extension: 'extension',
    fibchannel: 'channel',
    channel: 'channel',
    fibtimezone: 'timeZone',
    timezone: 'timeZone',
    fibspeedfan: 'speedFan',
    speedfan: 'speedFan',
    fibtimeextension: 'timeExtension',
    timeextension: 'timeExtension',
    fibcircles: 'circles',
    circles: 'circles',
    fibspiral: 'spiral',
    spiral: 'spiral',
    fibarcs: 'arcs',
    arcs: 'arcs',
    fibwedge: 'wedge',
    wedge: 'wedge',
    pitchfan: 'pitchfan',
    gannbox: 'box',
    box: 'box',
    gannfan: 'fan',
    fan: 'fan',
    gannsquare: 'square',
    square: 'square',
    rectangle: 'rectangle',
    rotatedrectangle: 'rotatedRectangle',
    circle: 'circle',
    triangle: 'triangle',
    ellipse: 'ellipse',
    arc: 'arc',
    path: 'path',
    polyline: 'polyline',
    curve: 'curve',
    doublecurve: 'doubleCurve',
    brush: 'brush',
    highlighter: 'highlighter',
    textannotation: 'text',
    textbox: 'text',
    text: 'text',
    anchoredtext: 'anchoredText',
    pricenote: 'priceNote',
    pricelabel: 'priceLabel',
    flagmark: 'flagMark',
    pin: 'pin',
    comment: 'comment',
    signpost: 'signpost',
    table: 'table',
    arrow: 'arrow',
    arrowmarkup: 'arrowMarkUp',
    arrowmarkdown: 'arrowMarkDown',
    longposition: 'longPosition',
    long: 'longPosition',
    shortposition: 'shortPosition',
    short: 'shortPosition',
    forecast: 'forecast',
    barspattern: 'barsPattern',
    projection: 'projection',
    pricerange: 'priceRange',
    daterange: 'dateRange',
    datepricerange: 'datePriceRange',
    elliottimpulsewave: 'elliottImpulseWave',
    elliottcorrectionwave: 'elliottCorrectionWave',
    elliotttrianglewave: 'elliottTriangleWave',
    elliottdoublecombowave: 'elliottDoubleComboWave',
    elliotttriplecombowave: 'elliottTripleComboWave',
    elliottwavepath: 'elliottWavePath'
  };

  const directKey = keyMap[norm];
  const item = directKey ? rawSidebarSvgMap[directKey] : rawSidebarSvgMap[nameOrKey];

  if (item) {
    return `<svg viewBox="${item.viewBox}" width="${size}" height="${size}" stroke-width="2" style="width:${size}px;height:${size}px;display:block;">${item.html}</svg>`;
  }

  // Fallback to standard trendline
  const def = rawSidebarSvgMap.trendLine;
  return `<svg viewBox="${def.viewBox}" width="${size}" height="${size}" stroke-width="2" style="width:${size}px;height:${size}px;display:block;">${def.html}</svg>`;
}


